DROP TABLE IF EXISTS `sistem_loglari`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sistem_loglari` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Log tekil kimligi (PK)',
  `kullanici_id` int DEFAULT NULL COMMENT 'Hata aninda islem yapan kullanici (Varsa)',
  `seviye` varchar(20) DEFAULT 'ERROR' COMMENT 'Log seviyesi (ERROR, WARNING, INFO)',
  `islem` varchar(100) NOT NULL COMMENT 'Hatanin alindigi Endpoint/URL',
  `detay` text NOT NULL COMMENT 'Hatanin teknik detayi ve Traceback metni',
  `insert_tarihi` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Hatanin olustugu tarih ve saat',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=348 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Uygulama genelindeki kritik hatalari (500) ve traceback ciktilarini tutan log tablosu.';
